/* --- Generador determinista de variantes por matrícula (paridad con Python) --- */
window.EXAMEN_VAR = (function () {
  function fnv1a(s) {
    var h = 0x811c9dc5;
    for (var i = 0; i < s.length; i++) {
      h ^= s.charCodeAt(i);
      h = Math.imul(h, 0x01000193) >>> 0;
    }
    return h >>> 0;
  }
  function normaliza(m) {
    return String(m || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  }
  function elegir(matricula, sal, arr) {
    return arr[fnv1a(normaliza(matricula) + '|' + sal) % arr.length];
  }
  function resolver(reactivo, matricula) {
    var v = {};
    Object.keys(reactivo.opciones).forEach(function (k) {
      var val = elegir(matricula, reactivo.id + ':' + k, reactivo.opciones[k]);
      if (Array.isArray(val)) {
        v[k] = val;
        for (var j = 0; j < val.length; j++) v[k + j] = val[j];
      } else {
        v[k] = val;
      }
    });
    return v;
  }
  function fmt(x) {
    if (typeof x !== 'number') return String(x);
    return String(x).replace('.', ',');
  }
  function texto(plantilla, v) {
    return plantilla.replace(/\{([A-Za-z0-9_]+)\}/g, function (_, k) {
      return (k in v) ? fmt(v[k]) : '{' + k + '}';
    });
  }
  return { fnv1a: fnv1a, normaliza: normaliza, elegir: elegir, resolver: resolver, texto: texto };
})();
